const downloadLink=(text,kind,params={})=>`<a class="button" href="${esc(url('/api/export',{kind,...params}))}" download>${esc(text)}</a>`;
function options(values,selected,empty){const selectedValues=new Set(Array.isArray(selected)?selected.map(String):[String(selected??'')]);let out=empty!==undefined?`<option value="">${esc(empty)}</option>`:'';for(const item of values){const value=typeof item==='object'?item.id:item,name=typeof item==='object'?(item.name??item.label??item.id):title(item);out+=`<option value="${esc(value)}"${selectedValues.has(String(value))?' selected':''}>${esc(name)}${item?.active===false?' (inactive)':''}</option>`;}if(selected!==undefined&&selected!==null&&selected!==''&&!Array.isArray(selected)&&!values.some(v=>String(typeof v==='object'?v.id:v)===String(selected)))out+=`<option selected value="${esc(selected)}">${esc(selected)} (reference needs attention)</option>`;return out;}
function notice(message){$('#notice').textContent=message;$('#notice').hidden=false;}
