function db(){return dbPromise??=new Promise((resolve,reject)=>{if(!globalThis.indexedDB)return reject(new Error('IndexedDB is unavailable.'));const r=indexedDB.open('open311-service-configuration',1);r.onupgradeneeded=()=>r.result.createObjectStore('records');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function storageKey(suffix){return 'service-configuration:'+String(workspace?.directory??location.origin)+':'+suffix;}
async function localRead(key){const values=await Promise.allSettled([(async()=>{const d=await db();return await new Promise((resolve,reject)=>{const r=d.transaction('records','readonly').objectStore('records').get(key);r.onsuccess=()=>resolve(r.result??null);r.onerror=()=>reject(r.error);});})(),Promise.resolve().then(()=>JSON.parse(localStorage.getItem(key)||'null'))]);return values.filter(v=>v.status==='fulfilled'&&v.value&&typeof v.value.savedAt==='number').map(v=>v.value).sort((a,b)=>b.savedAt-a.savedAt)[0]?.value??null;}
async function localWrite(key,value){const record={savedAt:Date.now(),value};const results=await Promise.allSettled([(async()=>{const d=await db();await new Promise((resolve,reject)=>{const tx=d.transaction('records','readwrite');tx.objectStore('records').put(record,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});})(),Promise.resolve().then(()=>localStorage.setItem(key,JSON.stringify(record)))]);if(results.every(r=>r.status==='rejected'))throw new Error('This browser could not save the working draft. Download the draft before closing the page.');}
async function api(path,body,identity=workspace?.workspaceId){let response;try{response=await fetch(path,{method:body===undefined?'GET':'POST',credentials:'same-origin',cache:'no-store',headers:{Accept:'application/json',...(body===undefined?{}:{'Content-Type':'application/json','X-Open311-Service-Configuration-Workspace':identity??''})},...(body===undefined?{}:{body:JSON.stringify(body)})});}catch(cause){const e=new Error('The workspace connection was interrupted. The original saved operation is available for recovery.');e.uncertain=body!==undefined;e.cause=cause;throw e;}let value;try{value=await response.json();}catch{const e=new Error('The workspace response could not be read.');e.uncertain=body!==undefined;throw e;}if(!response.ok||value?.error){const e=new Error(value?.error?.message??('Workspace request failed ('+response.status+').'));e.code=value?.error?.code;e.details=value?.error?.details;e.status=response.status;e.uncertain=body!==undefined&&response.status>=500;throw e;}return value;}
function header(){ $('#workspace-name').textContent=workspace?.directory?.split(/[\\/]/).filter(Boolean).pop()||'Service configuration';$('#workspace-meta').textContent='Revision '+(workspace?.revision??'—')+' · '+short(workspace?.workspaceId);for(const a of $$('[data-view]'))a.setAttribute('aria-current',a.dataset.view===ui.view?'page':'false');main.setAttribute('aria-busy',String(busy));$('#pending').hidden=!pending;if(pending)$('#pending-description').textContent=title(pending.path.replace('/api/',''))+' · '+pending.requestId+' · '+stamp(pending.createdAt);for(const b of $$('button')){if(busy&&!b.disabled&&!['dismiss-error','close-dialog'].includes(b.dataset.action)){b.dataset.busyDisabled='true';b.disabled=true;}else if(!busy&&b.dataset.busyDisabled){delete b.dataset.busyDisabled;b.disabled=false;}}}
async function refreshState(){workspace=await api('/api/state');header();}
async function write(path,payload){if(pending)throw new Error('Recover the saved operation before starting another workspace change.');const intent={requestId:uid('service-op'),expectedRevision:workspace.revision,...payload};pending={path,requestId:intent.requestId,body:intent,workspaceId:workspace.workspaceId,directory:workspace.directory,createdAt:new Date().toISOString()};await localWrite(storageKey('pending'),pending);header();try{const result=await api(path,intent,pending.workspaceId);await localWrite(storageKey('pending'),null);pending=null;await refreshState();return result;}catch(e){if(!e.uncertain){await localWrite(storageKey('pending'),null);pending=null;try{await refreshState();}catch{}}throw e;}finally{header();}}
async function recover(retry=false){if(!pending)return;const op=await api(url('/api/operation',{requestId:pending.requestId}));if(op?.state==='SUCCEEDED'){await localWrite(storageKey('pending'),null);pending=null;await refreshState();notice('The original operation completed. Its saved result is available.');return render();}if(!retry){notice('The original request has no saved completion yet. Resume it with the same request and body.');return;}const original=pending;try{await api(original.path,original.body,original.workspaceId);await localWrite(storageKey('pending'),null);pending=null;await refreshState();notice('The original saved operation completed.');await render();}catch(e){if(!e.uncertain){await localWrite(storageKey('pending'),null);pending=null;await refreshState();}throw e;}finally{header();}}
async function run(action){if(busy)return;busy=true;clearError();header();try{await action();}catch(e){showError(e);}finally{busy=false;header();const next=ui.queuedView;ui.queuedView=null;if(next&&next!==ui.view){location.hash=next;run(()=>navigate(next));}}}
function saveFile(name,text,type='application/json'){const blob=new Blob([text],{type}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),30000);}
function recordDialog(name,value){$('#record-title').textContent=name;$('#record-content').innerHTML=`<pre>${esc(pretty(value))}</pre>`;$('#record-dialog').showModal();}
function getPath(object,path){return path.split('.').reduce((value,key)=>value?.[key],object);}
function setPath(object,path,value){const keys=path.split('.');if(keys.some(k=>['__proto__','prototype','constructor'].includes(k)))throw new Error('Unsupported property name.');let p=object;for(let i=0;i<keys.length-1;i++){const key=keys[i];if(p[key]===undefined||p[key]===null)p[key]=/^\d+$/.test(keys[i+1])?[]:{};p=p[key];}p[keys.at(-1)]=value;}
function field(path,label,{type='text',values,empty,help='',required=false,min,max,rows=4,kind,placeholder=''}={}){const value=getPath(ui.draft,path),id='field-'+path.replace(/[^a-z0-9_-]/gi,'-'),common=`id="${esc(id)}" data-path="${esc(path)}"${required?' required':''}${min!==undefined?' min="'+esc(min)+'"':''}${max!==undefined?' max="'+esc(max)+'"':''}`;let input;if(type==='checkbox')input=`<input ${common} type="checkbox"${value?' checked':''}>`;else if(values)input=`<select ${common}${type==='multiple'?' multiple data-kind="selection"':''}>${options(values,value,empty)}</select>`;else if(type==='textarea')input=`<textarea ${common} rows="${rows}" data-kind="${esc(kind??'text')}" placeholder="${esc(placeholder)}">${esc(ui.rawDrafts[path]??(kind==='json'?pretty(value??null):kind==='optional-json'?(value===undefined?'':pretty(value)):kind==='lines'?list(value).join('\n'):kind==='words'?list(value).join(' '):value??''))}</textarea>`;else input=`<input ${common} type="${esc(type)}"${kind?' data-kind="'+esc(kind)+'"':''} value="${esc(value??'')}" placeholder="${esc(placeholder)}">`;return `<label class="${type==='checkbox'?'check':''}" for="${esc(id)}">${type==='checkbox'?input:''}<span>${esc(label)}</span>${type==='checkbox'?'':input}${help?`<small>${esc(help)}</small>`:''}</label>`;}
function table(headers,rows,empty='No saved records yet.'){return rows.length?`<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:`<p class="empty">${esc(empty)}</p>`;}
function pageHeading(name,text,actions=''){return `<div class="page-heading"><div><h1>${esc(name)}</h1>${text?`<p class="muted">${esc(text)}</p>`:''}</div><div class="actions">${actions}</div></div>`;}
function pager(page,action){const offset=Number(page.offset??0),limit=Number(page.limit??100),next=page.nextOffset??null;return `<div class="pager"><span>${count(page.total??0)} records · ${count(offset+((page.items?.length??0)>0?1:0))}–${count(offset+(page.items?.length??0))}</span><div class="actions">${button('Previous',action,`data-offset="${Math.max(0,offset-limit)}"${offset===0?' disabled':''}`)}${button('Next',action,`data-offset="${next??offset}"${next===null?' disabled':''}`)}</div></div>`;}
async function rememberDraft(){if(!ui.draft)return;await localWrite(storageKey('profile-draft:'+String(ui.profileId||'new')),{profileId:ui.profileId,definition:ui.draft,baseVersion:ui.baseVersion,baseDefinition:ui.baseDefinition,rawDrafts:ui.rawDrafts,savedAt:new Date().toISOString()});const el=$('#draft-status');if(el)el.textContent='Working draft saved in this browser.';}
function queueDraft(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>rememberDraft().catch(showError),250);const el=$('#draft-status');if(el)el.textContent='Saving working draft…';}
function inputDraft(el){if(!el.dataset.path)return;let value;if(el.type==='checkbox')value=el.checked;else if(el.dataset.kind==='selection')value=[...el.selectedOptions].map(o=>o.value);else if((el.dataset.kind==='optional-json'||el.dataset.kind==='optional-text')&&!el.value.trim()){const keys=el.dataset.path.split('.'),last=keys.pop(),parent=keys.reduce((v,k)=>v?.[k],ui.draft);if(parent)delete parent[last];delete ui.rawDrafts[el.dataset.path];el.setCustomValidity('');queueDraft();return;}else if(el.dataset.kind==='json'||el.dataset.kind==='optional-json'){ui.rawDrafts[el.dataset.path]=el.value;try{value=JSON.parse(el.value);el.setCustomValidity('');delete ui.rawDrafts[el.dataset.path];}catch{el.setCustomValidity('Enter valid JSON for this field.');queueDraft();return;}}else if(el.dataset.kind==='lines')value=el.value.split(/\r?\n/).map(s=>s.trim()).filter(Boolean);else if(el.dataset.kind==='words')value=el.value.trim()?el.value.trim().split(/\s+/):[];else if(el.type==='number')value=el.value===''?null:Number(el.value);else value=el.value;setPath(ui.draft,el.dataset.path,value);queueDraft();}
