const templateContract={"nativeComcateMergeNames":["{{issue_number}}","{{case_number}}"],"handoverRendererNames":["{{agency_name}}","{{service_category}}","{{department_name}}","{{assignee_name}}","{{request_created_date}}","{{request_updated_date}}","{{due_date}}","{{source_status}}","{{source_status_notes}}","{{location}}","{{work_order_ids}}","{{completion_note}}","{{progress_summary}}","{{magic_link}}"],"facts":["Selected placeholders require actual mapped values; missing values remain visible in the preview.","Use source closure and literal resolution wording. A closed source may describe a citation or administrative disposition.","The magic link must be an explicitly supplied permitted HTTPS citizen URL.","Review audience and source-derived progress wording for each rendered message.","Resident assignee_name, completion_note and progress_summary require explicitly supplied residentWording values."]};

function definitionOf(record){return record?.definition??record??null;}
function freshDefinition(){return {name:'',agency:{id:uid('agency'),name:'',timeZone:'',calendar:{kind:'calendar_days',weekdays:[1,2,3,4,5],holidays:[]}},departments:[],roles:[],groups:[],staff:[],categories:[],templates:[],routes:[],sourceProfiles:[],rollout:[],note:''};}
async function openProfile(id){ui.profileId=id||'';let current=null;detail=null;if(id){detail=await api(url('/api/profile',{id}));current=detail.profile;}const draft=await localRead(storageKey('profile-draft:'+String(id||'new')));ui.draft=draft?.definition?copy(draft.definition):current?copy(current.definition):freshDefinition();ui.baseDefinition=draft?.baseDefinition??(current?copy(current.definition):null);ui.baseVersion=draft?.baseVersion??current?.versionId??null;ui.rawDrafts=draft?.rawDrafts??{};ui.staleDraft=!!(current&&draft&&draft.baseVersion!==current.versionId);ui.section=sections.includes(ui.section)?ui.section:'agency';ui.view='profiles';location.hash='profiles';await render();}
function collectionHeading(label,kind,path=kind){return `<div class="section-heading"><h2>${esc(label)}</h2>${button('Add '+(kind==='categories'?'category':kind==='staff'?'staff member':kind==='sourceProfiles'?'source profile':kind==='rollout'?'phase':kind.replace(/s$/,'')),'add-item',`data-kind="${esc(kind)}" data-path="${esc(path)}"`)}</div>`;}
